      AND ph.state='ready' AND pl.pause_reason IS NULL AND pl.due_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')))) OR (NEW.reconciliation_id IS NOT NULL AND EXISTS(SELECT 1 FROM archive_publication_reconciliation_receipts rc JOIN archive_publications rp ON rp.publication_id=rc.publication_id JOIN history_runtime rh ON rh.id=1 AND rh.generation=rc.execution_generation WHERE rc.reconciliation_id=NEW.reconciliation_id AND rc.publication_id=NEW.publication_id AND rc.execution_generation=NEW.generation AND rh.state='ready' AND ((((json_type(rc.descriptor_json,'$.publication_id') IS 'text' AND json_extract(rc.descriptor_json,'$.publication_id') IS rp.publication_id AND json_type(rc.descriptor_json,'$.verification_id') IS 'text' AND json_extract(rc.descriptor_json,'$.verification_id') IS rp.verification_id) AND (json_type(rc.descriptor_json,'$.generation') IS 'text' AND json_extract(rc.descriptor_json,'$.generation') IS rp.generation AND (json_type(rc.descriptor_json,'$.run_id') IS 'text' AND json_extract(rc.descriptor_json,'$.run_id') IS rp.run_id AND json_type(rc.descriptor_json,'$.snapshot_commit_token') IS 'text' AND json_extract(rc.descriptor_json,'$.snapshot_commit_token') IS rp.snapshot_commit_token))) AND ((json_type(rc.descriptor_json,'$.graph_sha256') IS 'text' AND json_extract(rc.descriptor_json,'$.graph_sha256') IS rp.graph_sha256 AND (json_type(rc.descriptor_json,'$.validator_version') IS 'integer' AND json_extract(rc.descriptor_json,'$.validator_version') IS rp.validator_version AND json_type(rc.descriptor_json,'$.archive_id') IS 'text' AND json_extract(rc.descriptor_json,'$.archive_id') IS rp.archive_id)) AND (json_type(rc.descriptor_json,'$.center_id') IS 'text' AND json_extract(rc.descriptor_json,'$.center_id') IS rp.center_id AND (json_type(rc.descriptor_json,'$.month') IS 'text' AND json_extract(rc.descriptor_json,'$.month') IS rp.month AND json_type(rc.descriptor_json,'$.timezone') IS 'text' AND json_extract(rc.descriptor_json,'$.timezone') IS rp.timezone)))) AND (((json_type(rc.descriptor_json,'$.root_reference_json') IS 'text' AND json_extract(rc.descriptor_json,'$.root_reference_json') IS rp.root_reference_json AND (json_type(rc.descriptor_json,'$.header_json') IS 'text' AND json_extract(rc.descriptor_json,'$.header_json') IS rp.header_json AND json_type(rc.descriptor_json,'$.header_sha256') IS 'text' AND json_extract(rc.descriptor_json,'$.header_sha256') IS rp.header_sha256)) AND (json_type(rc.descriptor_json,'$.manifest_object_key') IS 'text' AND json_extract(rc.descriptor_json,'$.manifest_object_key') IS rp.manifest_object_key AND (json_type(rc.descriptor_json,'$.manifest_sha256') IS 'text' AND json_extract(rc.descriptor_json,'$.manifest_sha256') IS rp.manifest_sha256 AND json_type(rc.descriptor_json,'$.format') IS 'text' AND json_extract(rc.descriptor_json,'$.format') IS rp.format))) AND ((json_type(rc.descriptor_json,'$.locator_version') IS 'integer' AND json_extract(rc.descriptor_json,'$.locator_version') IS rp.locator_version AND (json_type(rc.descriptor_json,'$.record_count') IS 'integer' AND json_extract(rc.descriptor_json,'$.record_count') IS rp.record_count AND json_type(rc.descriptor_json,'$.request_count') IS 'integer' AND json_extract(rc.descriptor_json,'$.request_count') IS rp.request_count)) AND (json_type(rc.descriptor_json,'$.counts_json') IS 'text' AND json_extract(rc.descriptor_json,'$.counts_json') IS rp.counts_json AND (json_type(rc.descriptor_json,'$.locator_digest') IS 'text' AND json_extract(rc.descriptor_json,'$.locator_digest') IS rp.locator_digest AND json_type(rc.descriptor_json,'$.published_at') IS 'text' AND json_extract(rc.descriptor_json,'$.published_at') IS rp.published_at))))))))
BEGIN SELECT RAISE(ABORT,'ARCHIVE_PUBLICATION_AVAILABILITY_INVALID'); END;
CREATE TRIGGER archive_publication_availability_update_guard BEFORE UPDATE ON archive_publication_availability
WHEN NEW.publication_id IS NOT OLD.publication_id OR NOT ((NEW.status='unavailable' AND NEW.generation IS OLD.generation AND NEW.reconciliation_id IS OLD.reconciliation_id) OR (NEW.status='ready' AND NEW.reconciliation_id IS NOT NULL AND EXISTS(SELECT 1 FROM archive_publication_reconciliation_receipts rc JOIN archive_publications rp ON rp.publication_id=rc.publication_id JOIN history_runtime rh ON rh.id=1 AND rh.generation=rc.execution_generation WHERE rc.reconciliation_id=NEW.reconciliation_id AND rc.publication_id=NEW.publication_id AND rc.execution_generation=NEW.generation AND rh.state='ready' AND ((((json_type(rc.descriptor_json,'$.publication_id') IS 'text' AND json_extract(rc.descriptor_json,'$.publication_id') IS rp.publication_id AND json_type(rc.descriptor_json,'$.verification_id') IS 'text' AND json_extract(rc.descriptor_json,'$.verification_id') IS rp.verification_id) AND (json_type(rc.descriptor_json,'$.generation') IS 'text' AND json_extract(rc.descriptor_json,'$.generation') IS rp.generation AND (json_type(rc.descriptor_json,'$.run_id') IS 'text' AND json_extract(rc.descriptor_json,'$.run_id') IS rp.run_id AND json_type(rc.descriptor_json,'$.snapshot_commit_token') IS 'text' AND json_extract(rc.descriptor_json,'$.snapshot_commit_token') IS rp.snapshot_commit_token))) AND ((json_type(rc.descriptor_json,'$.graph_sha256') IS 'text' AND json_extract(rc.descriptor_json,'$.graph_sha256') IS rp.graph_sha256 AND (json_type(rc.descriptor_json,'$.validator_version') IS 'integer' AND json_extract(rc.descriptor_json,'$.validator_version') IS rp.validator_version AND json_type(rc.descriptor_json,'$.archive_id') IS 'text' AND json_extract(rc.descriptor_json,'$.archive_id') IS rp.archive_id)) AND (json_type(rc.descriptor_json,'$.center_id') IS 'text' AND json_extract(rc.descriptor_json,'$.center_id') IS rp.center_id AND (json_type(rc.descriptor_json,'$.month') IS 'text' AND json_extract(rc.descriptor_json,'$.month') IS rp.month AND json_type(rc.descriptor_json,'$.timezone') IS 'text' AND json_extract(rc.descriptor_json,'$.timezone') IS rp.timezone)))) AND (((json_type(rc.descriptor_json,'$.root_reference_json') IS 'text' AND json_extract(rc.descriptor_json,'$.root_reference_json') IS rp.root_reference_json AND (json_type(rc.descriptor_json,'$.header_json') IS 'text' AND json_extract(rc.descriptor_json,'$.header_json') IS rp.header_json AND json_type(rc.descriptor_json,'$.header_sha256') IS 'text' AND json_extract(rc.descriptor_json,'$.header_sha256') IS rp.header_sha256)) AND (json_type(rc.descriptor_json,'$.manifest_object_key') IS 'text' AND json_extract(rc.descriptor_json,'$.manifest_object_key') IS rp.manifest_object_key AND (json_type(rc.descriptor_json,'$.manifest_sha256') IS 'text' AND json_extract(rc.descriptor_json,'$.manifest_sha256') IS rp.manifest_sha256 AND json_type(rc.descriptor_json,'$.format') IS 'text' AND json_extract(rc.descriptor_json,'$.format') IS rp.format))) AND ((json_type(rc.descriptor_json,'$.locator_version') IS 'integer' AND json_extract(rc.descriptor_json,'$.locator_version') IS rp.locator_version AND (json_type(rc.descriptor_json,'$.record_count') IS 'integer' AND json_extract(rc.descriptor_json,'$.record_count') IS rp.record_count AND json_type(rc.descriptor_json,'$.request_count') IS 'integer' AND json_extract(rc.descriptor_json,'$.request_count') IS rp.request_count)) AND (json_type(rc.descriptor_json,'$.counts_json') IS 'text' AND json_extract(rc.descriptor_json,'$.counts_json') IS rp.counts_json AND (json_type(rc.descriptor_json,'$.locator_digest') IS 'text' AND json_extract(rc.descriptor_json,'$.locator_digest') IS rp.locator_digest AND json_type(rc.descriptor_json,'$.published_at') IS 'text' AND json_extract(rc.descriptor_json,'$.published_at') IS rp.published_at))))))))
BEGIN SELECT RAISE(ABORT,'ARCHIVE_PUBLICATION_AVAILABILITY_INVALID'); END;

CREATE TRIGGER archive_reconciliation_generation_changed AFTER UPDATE OF generation ON history_runtime
WHEN NEW.generation!=OLD.generation
BEGIN UPDATE archive_publication_reconciliation_jobs SET state='invalid',lease_token=NULL,lease_expires_at=NULL,revision=revision+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE state IN ('pending','running'); END;
CREATE TRIGGER archive_reconciliation_session_invalidated AFTER UPDATE OF status ON archive_semantic_sessions
WHEN NEW.status='invalid'
BEGIN UPDATE archive_publication_reconciliation_jobs SET state='invalid',lease_token=NULL,lease_expires_at=NULL,revision=revision+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE verification_id=NEW.verification_id AND execution_generation=NEW.generation AND state IN ('pending','running'); END;
CREATE TRIGGER archive_reconciliation_run_invalidated AFTER UPDATE OF status ON archive_semantic_runs
WHEN NEW.status='invalid'
BEGIN UPDATE archive_publication_reconciliation_jobs SET state='invalid',lease_token=NULL,lease_expires_at=NULL,revision=revision+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE run_id=NEW.run_id AND state IN ('pending','running'); END;

CREATE TRIGGER archive_publication_reconciliation_jobs_no_delete BEFORE DELETE ON archive_publication_reconciliation_jobs
BEGIN SELECT RAISE(ABORT,'IMMUTABLE_ARCHIVE_RECONCILIATION'); END;

